"""Product analytics dashboard: conversion statistics over customer sessions."""


def conversion_rate(events):
    """The conversion rate of a list of sessions. See SPEC.md section 1."""
    hits = sum(1 for e in events if e["converted"])
    return hits / len(events)


def pooled_conversion_rate(groups):
    """The pooled conversion rate across groups of sessions. See SPEC.md section 2."""
    rates = [conversion_rate(evts) for evts in groups.values()]
    return sum(rates) / len(rates)


def conversions_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    return sum(daily_counts[-days - 1:])


def conversion_rate_by_group(groups):
    """The conversion rate of each group. See SPEC.md section 9."""
    return {name: conversion_rate(evts) for name, evts in groups.items()}


def longest_flag_streak(daily_counts):
    """Longest run of days with flagged sessions. See SPEC.md section 10."""
    best = cur = 0
    for c in daily_counts:
        if c:
            cur += 1
            best = max(best, cur)
    return best
"""Product analytics dashboard: conversion statistics over customer sessions."""


def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    out = []
    for line in lines:
        id_, day, flag = line.strip().split(",")
        out.append({"id": id_, "day": int(day), "converted": bool(flag)})
    return out


def dedupe_sessions(events):
    """Remove duplicate sessions. See SPEC.md section 5."""
    seen = {}
    for e in events:
        if e["id"] not in seen:
            seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Daily counts of converted sessions. See SPEC.md section 6."""
    counts = {}
    for e in events:
        if e["converted"]:
            counts[e["day"]] = counts.get(e["day"], 0) + 1
    return [counts[d] for d in sorted(counts)]
